using UnityEngine;
using UnityEditor;
using System;
using System.Collections.Generic;
public static class MakongBalanceSetup {
 public static readonly string[] EquipmentIds=MakongPreparationEquipment.Ids;
 public static void ApplyBalance(){var catalog=EnemyCharacterCatalog.Current;var boss=catalog.FindId("Makong");boss.category=EnemyRank.Subjefe;boss.reservedForEvents=true;boss.overrideGrowth=true;boss.growth=new EnemyGrowth{health=1f/9,strength=4f/63,defense=.06f,luck=.03f};boss.health=105;boss.strength=8;boss.defense=6;boss.luck=5;boss.specialDamage=10;boss.specialHits=1;EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssetIfDirty(catalog);
  var s=MakongSpecialSettings.Current;s.earthquakeCooldownTurns=3;s.swallowCooldownTurns=4;s.summonCooldownTurns=4;s.normalTurnsBetweenSpecials=1;s.maximumSwallows=2;s.maximumHelpers=2;s.healBelowFraction=.45f;s.healFraction=0;s.healFlat=18;EditorUtility.SetDirty(s);AssetDatabase.SaveAssetIfDirty(s);
  var character=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");var list=new List<PlayerEquipment>(character.equipment);string[] names={"Power Glove MK-II","T-Shirt de Resistencia","Medias del Glitch"};int[] hp={0,12,6},atk={7,0,0},def={0,7,2},luck={3,0,6};for(int n=0;n<3;n++){var existing=list.Find(e=>e!=null&&e.id==EquipmentIds[n]);if(existing==null){existing=new PlayerEquipment(names[n],(n+1).ToString(),hp[n],atk[n],def[n],luck[n]);existing.id=EquipmentIds[n];existing.description="Equipamiento de preparación para Makong.";var initial=Array.Find(character.equipment,e=>e!=null&&e.id==character.initialEquipmentIds[n]);existing.icon=initial!=null?initial.icon:null;list.Add(existing);}}character.equipment=list.ToArray();EditorUtility.SetDirty(character);AssetDatabase.SaveAssetIfDirty(character);
 }
 public static string Place(){var plan=DungeonMapSettings.Current;var regions=plan.regions!=null?plan.regions:DungeonRegionSettings.Current;var entities=plan.entities;if(entities==null)throw new Exception("Falta asset de objetos");var bossCell=new Vector2Int(12,53);if(!plan.IsFloor(bossCell))throw new Exception("La casilla autorizada de Makong no es suelo");if(entities.objects.Exists(e=>e.cell==bossCell))throw new Exception("Casilla de Makong ocupada");
  var placements=new List<PlacedEnemyDefinition>(regions.placedEnemies);if(!placements.Exists(e=>e.id=="makong.first-sub-boss"))placements.Add(new PlacedEnemyDefinition{id="makong.first-sub-boss",speciesId="Makong",cell=bossCell,fixedLevel=10,randomLevel=false,category=PlacedEnemyCategory.Elite,respawn=false,unique=true,countsTowardLimit=false});
  Vector2Int[] cells={new Vector2Int(17,26),new Vector2Int(2,44),new Vector2Int(21,51)};string[] ids={"makong.prep.glove","makong.prep.shirt","makong.prep.socks"};string[] labels={"Cofre — Power Glove MK-II","Cofre — T-Shirt de Resistencia","Cofre — Medias del Glitch"};
  for(int n=0;n<3;n++){if(!plan.IsFloor(cells[n]))throw new Exception("Cofre fuera de suelo");if(entities.objects.Exists(e=>e.cell==cells[n]&&e.id!=ids[n])||placements.Exists(e=>e.cell==cells[n]))throw new Exception("Casilla de cofre ocupada");if(!entities.objects.Exists(e=>e.id==ids[n]))entities.objects.Add(new DungeonMapEntity{id=ids[n],displayName=labels[n],kind=DungeonEntityKind.Chest,cell=cells[n],chestKind=DungeonChestKind.Normal,contentId=EquipmentIds[n],quantity=1});}
  if(!placements.Exists(e=>e.id=="makong.prep.shirt-guard"))placements.Add(new PlacedEnemyDefinition{id="makong.prep.shirt-guard",speciesId="Hongo",cell=new Vector2Int(4,45),fixedLevel=4,randomLevel=false,respawn=false,unique=true,countsTowardLimit=true});
  var blocked=new HashSet<Vector2Int>();foreach(var e in entities.objects)if(e.kind==DungeonEntityKind.Chest||e.kind==DungeonEntityKind.NPC||e.kind==DungeonEntityKind.Savepoint)blocked.Add(e.cell);
  Vector2Int start=plan.includeLegacyObjects&&RefugeSettings.Current!=null?RefugeSettings.Current.startCell:plan.startCell;var visited=Reachable(plan,start,blocked);if(!visited.Contains(bossCell))throw new Exception("Los objetos bloquean el acceso al subjefe");for(int n=0;n<3;n++){bool reachable=false;foreach(var dir in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right})reachable|=visited.Contains(cells[n]+dir);if(!reachable)throw new Exception("Cofre inaccesible "+cells[n]);}
  regions.placedEnemies=placements.ToArray();EditorUtility.SetDirty(regions);EditorUtility.SetDirty(entities);AssetDatabase.SaveAssetIfDirty(regions);AssetDatabase.SaveAssetIfDirty(entities);return "Makong (12,53), cofres (17,26), (2,44), (21,51); Hongo LV4 opcional (4,45). Navegación validada.";
 }
 static HashSet<Vector2Int> Reachable(DungeonMapSettings plan,Vector2Int start,HashSet<Vector2Int> blocked){var visited=new HashSet<Vector2Int>();var queue=new Queue<Vector2Int>();visited.Add(start);queue.Enqueue(start);while(queue.Count>0){var at=queue.Dequeue();foreach(var d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var next=at+d;if(plan.IsFloor(next)&&!blocked.Contains(next)&&visited.Add(next))queue.Enqueue(next);}}return visited;}
}
